-- 001_init: THESIS persistence schema (TigerData / PostgreSQL).
-- Additive only (CREATE ... IF NOT EXISTS); nothing is dropped or rewritten. All times are TIMESTAMPTZ (UTC).
-- IDs are prefixed random UUIDs generated by the app (usr_, ses_, evt_, th_, art_, mat_, ntf_, conv_, msg_).

-- The existing synchronous store keys (feed, council, sentimentCache, thesis, thesisMatches,
-- notifyLastSentDate, paperLedger), written through from server/store.js so they survive restarts.
CREATE TABLE IF NOT EXISTS kv_store (
  key         TEXT PRIMARY KEY,
  value       JSONB,
  updated_at  TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- Demo-grade identity: a user id the client sends as X-User-Id. NOT authentication.
CREATE TABLE IF NOT EXISTS users (
  user_id       TEXT PRIMARY KEY,
  display_name  TEXT,
  preferences   JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

-- handleThesisAction state, saved only by the server with a version compare-and-swap.
CREATE TABLE IF NOT EXISTS onboarding_sessions (
  session_id         TEXT PRIMARY KEY,
  user_id            TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  state              JSONB NOT NULL,
  version            INTEGER NOT NULL DEFAULT 0 CHECK (version >= 0),
  stage              TEXT NOT NULL,
  next_actions       JSONB NOT NULL DEFAULT '[]'::jsonb,
  last_display_text  TEXT,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS onboarding_sessions_user_idx ON onboarding_sessions (user_id, updated_at DESC);

-- One row per session action: what the user said or chose, and when (the onboarding part of the timeline).
CREATE TABLE IF NOT EXISTS session_events (
  event_id       TEXT PRIMARY KEY,
  session_id     TEXT NOT NULL REFERENCES onboarding_sessions (session_id) ON DELETE CASCADE,
  user_id        TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  action         TEXT NOT NULL,
  payload        JSONB NOT NULL DEFAULT '{}'::jsonb,
  ok             BOOLEAN NOT NULL,
  error_code     TEXT,
  stage_after    TEXT,
  version_after  INTEGER,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS session_events_session_idx ON session_events (session_id, created_at);

-- Confirmed theses. Many per user; a saved thesis is never overwritten.
CREATE TABLE IF NOT EXISTS theses (
  thesis_id            TEXT PRIMARY KEY,
  user_id              TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  session_id           TEXT REFERENCES onboarding_sessions (session_id) ON DELETE SET NULL,
  origin               TEXT NOT NULL CHECK (origin IN ('session', 'goals_text', 'legacy')),
  legacy_id            TEXT,
  data                 JSONB NOT NULL,
  goal                 TEXT,
  selected_assets      JSONB NOT NULL DEFAULT '[]'::jsonb,
  assumptions          JSONB NOT NULL DEFAULT '[]'::jsonb,
  assumption_version   INTEGER NOT NULL DEFAULT 1,
  monitoring_status    TEXT NOT NULL DEFAULT 'active' CHECK (monitoring_status IN ('active', 'paused')),
  source_confirmed_at  TIMESTAMPTZ,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  confirmed_at         TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS theses_user_idx ON theses (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS theses_active_idx ON theses (monitoring_status) WHERE monitoring_status = 'active';
CREATE UNIQUE INDEX IF NOT EXISTS theses_session_confirm_uq ON theses (session_id, source_confirmed_at) WHERE session_id IS NOT NULL;
CREATE UNIQUE INDEX IF NOT EXISTS theses_legacy_uq ON theses (user_id, legacy_id) WHERE legacy_id IS NOT NULL;

-- Each distinct news article once (ticker + normalized headline); re-sent batches only bump last_seen_at.
CREATE TABLE IF NOT EXISTS news_articles (
  article_id      TEXT PRIMARY KEY,
  dedupe_key      TEXT NOT NULL UNIQUE,
  ticker          TEXT,
  headline        TEXT NOT NULL,
  summary         TEXT,
  publisher       TEXT,
  url             TEXT,
  published_at    TIMESTAMPTZ,
  ingested_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  first_run_date  DATE,
  seen_count      INTEGER NOT NULL DEFAULT 1
);
CREATE INDEX IF NOT EXISTS news_articles_ticker_idx ON news_articles (ticker, published_at DESC);

-- Which articles were evaluated against which thesis version, and when (matched or not).
CREATE TABLE IF NOT EXISTS thesis_article_checks (
  thesis_id           TEXT NOT NULL REFERENCES theses (thesis_id) ON DELETE CASCADE,
  article_id          TEXT NOT NULL REFERENCES news_articles (article_id) ON DELETE CASCADE,
  assumption_version  INTEGER NOT NULL,
  matched             BOOLEAN NOT NULL,
  analyzed_by         TEXT,
  checked_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (thesis_id, article_id, assumption_version)
);

-- matchNewsDetailed output, one row per thesis + article + assumption version. History is kept: later news
-- runs add rows, they never overwrite earlier assessments (only an "unanalyzed" placeholder is upgraded).
CREATE TABLE IF NOT EXISTS thesis_matches (
  match_id            TEXT PRIMARY KEY,
  thesis_id           TEXT NOT NULL REFERENCES theses (thesis_id) ON DELETE CASCADE,
  article_id          TEXT NOT NULL REFERENCES news_articles (article_id) ON DELETE CASCADE,
  assumption_version  INTEGER NOT NULL,
  assumption_index    INTEGER NOT NULL,
  assumption_text     TEXT,
  stance              TEXT NOT NULL CHECK (stance IN ('supports', 'challenges', 'neutral')),
  assessed_stance     TEXT CHECK (assessed_stance IS NULL OR assessed_stance IN ('supports', 'challenges', 'neutral')),
  relevance           TEXT,
  evidence            TEXT,
  provisional         BOOLEAN,
  unanalyzed          BOOLEAN NOT NULL DEFAULT false,
  why_it_matters      TEXT,
  analyzed_by         TEXT,
  model               TEXT,
  match               JSONB NOT NULL,
  assessed_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (thesis_id, article_id, assumption_version)
);
CREATE INDEX IF NOT EXISTS thesis_matches_thesis_idx ON thesis_matches (thesis_id, assessed_at DESC);
CREATE INDEX IF NOT EXISTS thesis_matches_article_idx ON thesis_matches (article_id);

-- Every alert attempt and its real outcome. idempotency_key blocks re-sends when a batch is reprocessed.
CREATE TABLE IF NOT EXISTS notifications (
  notification_id  TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  thesis_id        TEXT NOT NULL REFERENCES theses (thesis_id) ON DELETE CASCADE,
  match_id         TEXT NOT NULL REFERENCES thesis_matches (match_id) ON DELETE CASCADE,
  type             TEXT NOT NULL,
  channel          TEXT NOT NULL DEFAULT 'email',
  status           TEXT NOT NULL CHECK (status IN ('pending', 'sending', 'sent', 'failed', 'skipped')),
  reason           TEXT,
  attempts         INTEGER NOT NULL DEFAULT 0,
  idempotency_key  TEXT NOT NULL UNIQUE,
  payload          JSONB,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_attempt_at  TIMESTAMPTZ,
  sent_at          TIMESTAMPTZ,
  failed_at        TIMESTAMPTZ
);
CREATE INDEX IF NOT EXISTS notifications_thesis_idx ON notifications (thesis_id, created_at DESC);
CREATE INDEX IF NOT EXISTS notifications_retry_idx ON notifications (status) WHERE status IN ('failed', 'pending', 'sending');

-- Thesis research chat. An investigation conversation keeps the match (and so the article) it was opened on.
CREATE TABLE IF NOT EXISTS chat_conversations (
  conversation_id  TEXT PRIMARY KEY,
  user_id          TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  thesis_id        TEXT NOT NULL REFERENCES theses (thesis_id) ON DELETE CASCADE,
  mode             TEXT NOT NULL CHECK (mode IN ('general', 'investigation')),
  match_id         TEXT REFERENCES thesis_matches (match_id) ON DELETE RESTRICT,
  title            TEXT,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK ((mode = 'investigation') = (match_id IS NOT NULL))
);
CREATE INDEX IF NOT EXISTS chat_conversations_thesis_idx ON chat_conversations (thesis_id, updated_at DESC);

CREATE TABLE IF NOT EXISTS chat_messages (
  message_id       TEXT PRIMARY KEY,
  conversation_id  TEXT NOT NULL REFERENCES chat_conversations (conversation_id) ON DELETE CASCADE,
  thesis_id        TEXT NOT NULL REFERENCES theses (thesis_id) ON DELETE CASCADE,
  user_id          TEXT NOT NULL REFERENCES users (user_id) ON DELETE CASCADE,
  seq              INTEGER NOT NULL CHECK (seq > 0),
  role             TEXT NOT NULL CHECK (role IN ('user', 'assistant')),
  content          TEXT NOT NULL,
  citations        JSONB NOT NULL DEFAULT '[]'::jsonb,
  segments         JSONB NOT NULL DEFAULT '[]'::jsonb,
  meta             JSONB NOT NULL DEFAULT '{}'::jsonb,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (conversation_id, seq)
);
CREATE INDEX IF NOT EXISTS chat_messages_thesis_idx ON chat_messages (thesis_id, created_at);
